def priority(item: float, bins: np.ndarray) -> np.ndarray:
    target = bins / 2.0
    distance = np.abs((bins - item) - target)
    epsilon = 1e-8
    return 1.0 / (distance + epsilon)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    current_loads = bins - item
    avg_remaining = np.mean(current_loads)
    distance = np.abs(current_loads - avg_remaining)
    epsilon = 1e-8
    return 1.0 / (distance + epsilon)
